// LayersViewPanel — a Photoshop-style canvas Layers browser for a live `GraphCanvas`.
// Lists every layer registered on the canvas (background / graph / minimap …) as
// a file-tree, top layer first. The Graph layer expands into its painted contents
// grouped by node/edge type with live counts; each type expands into its
// individual elements. Each layer row carries a visibility eye on the right;
// every layer/element row also has a right-click context menu
// (Focus · Select · Hide/Show).
//
// Note: unlike the pure-presentational `views/` components, this one takes a
// *live* `GraphCanvas` and drives visibility on it. It stays within the package's
// import rules — `@invana/graph` is imported for **types only** and all chrome is
// `@invana/ui` — but it is engine-bound by design (a browser needs the live
// scene). Keep it here as the reusable canvas Layers panel; don't add engine
// *value* imports (`@invana/canvas` / `pixi`).
//
// Visibility runs through the first-class `@invana/graph` API:
//   - element hide/show  → `store.setNodeHidden` / `store.setEdgeHidden`
//     (incident edges follow a hidden node automatically via the store's
//     derived cascade — no hand-rolled edge bookkeeping),
//   - element hidden test → `store.isNodeHidden` / `store.isEdgeHidden`,
//   - whole-layer toggle  → `layer.setVisible(...)` (auto-repaints + emits
//     `scene:layer:visibilitychange`).
// The panel refreshes on the store's `node:visibility` / `edge:visibility`
// events and the canvas bus `scene:layer:visibilitychange`.

import type {
  ClickSelectBehaviour,
  GraphCanvas,
  GraphLayer,
  GraphStore,
} from '@invana/graph';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
  type TreeItem,
  TreeView,
} from '@invana/ui';
import {
  ArrowRight,
  Boxes,
  Circle,
  Crosshair,
  Eye,
  EyeOff,
  Frame,
  Image as ImageIcon,
  Layers,
  Map as MapIcon,
  MoreHorizontal,
  MousePointer2,
  Network,
  Spline,
} from 'lucide-react';
import type {
  ElementType,
  MouseEvent as ReactMouseEvent,
  ReactNode,
} from 'react';
import {
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useReducer,
  useRef,
  useState,
} from 'react';
import { GraphCanvasContext } from '@invana/canvas-react';

export interface LayersViewPanelProps {
  /**
   * The live canvas engine. **Optional** — omit it inside a `<GraphCanvas>` /
   * `GraphCanvasApp` tree and the panel binds to the nearest one via
   * `GraphCanvasContext` (rendering empty until the engine is ready). Pass it
   * explicitly to target a specific instance from outside that subtree.
   */
  canvas?: GraphCanvas | null;
}

// "Focus" zooms in to at least this scale (matches the canvas context menu).
const FOCUS_ZOOM = 2;

// How many individual elements a type shows before collapsing the rest behind a
// "Show more". The design-kit TreeItem renders expanded by default, so an
// uncapped list would paint every node/edge of a large graph at once — on a
// 100k-node / 500k-edge canvas that would freeze the tab. "Show more" reveals
// another page on demand.
const DEFAULT_SHOWN = 15;
const REVEAL_STEP = 15;

// Property keys tried, in order, for a human-readable element label before
// falling back to the raw store id.
const NAME_KEYS = ['name', 'title', 'label', 'displayName', 'id'];

// What a right-click landed on. Type/group/"show more" rows have no menu.
type MenuTarget =
  | { kind: 'node'; id: string }
  | { kind: 'edge'; id: string }
  | { kind: 'group'; id: string }
  | { kind: 'layer'; id: string };

interface RowCtx {
  limitFor: (typeKey: string) => number;
  onReveal: (typeKey: string) => void;
  onLeafClick: (kind: 'node' | 'edge', id: string) => void;
  refresh: () => void;
}

function elementLabel(data: unknown, fallback: string): string {
  if (data && typeof data === 'object') {
    const rec = data as Record<string, unknown>;
    for (const key of NAME_KEYS) {
      const v = rec[key];
      if (typeof v === 'string' && v.trim()) return v;
      if (typeof v === 'number') return String(v);
    }
  }
  return fallback;
}

// Classes matching TreeItem's own `hover:bg-accent hover:text-accent-foreground`,
// applied imperatively to the right-clicked row so it stays highlighted while its
// context menu is open (the pointer moves to the menu and drops the hover). Done
// on the DOM node rather than via React state so opening the menu doesn't force a
// full store re-scan just to repaint one row.
const ACTIVE_ROW_CLASSES = ['bg-accent', 'text-accent-foreground'];

// The label lives here, not in TreeItem's own `label` slot (left blank) — the
// slot renders before the row's controls and can't host a surface covering the
// whole row. Rendering the row body here also lets the trailing eye span the full
// width, Photoshop-style. The `data-menu-*` attributes let the wrapper's
// delegated right-click handler resolve which element this row targets, no matter
// where in the row (text, padding, blank space) the click lands.
function RowContent({
  icon,
  label,
  trailing,
  muted,
  menuTarget,
}: {
  icon: ReactNode;
  label: string;
  trailing?: ReactNode;
  muted?: boolean;
  menuTarget?: MenuTarget;
}) {
  return (
    <div
      className="flex min-w-0 flex-1 select-none items-center gap-2"
      data-menu-kind={menuTarget?.kind}
      data-menu-id={menuTarget?.id}
    >
      {icon}
      {/* `min-w-0` is essential: without it `flex-1` keeps `min-width:auto`, so a
          long single-line id (a hash) can't shrink and forces the row wider than
          the panel instead of truncating. `text-left` keeps it hugging the icon. */}
      <span
        title={label}
        className={`min-w-0 flex-1 truncate text-left ${muted ? 'text-muted-foreground/50 line-through' : ''}`}
      >
        {label}
      </span>
      {trailing}
    </div>
  );
}

// A per-layer eye toggle in the row's trailing slot. Stops propagation so the
// flip stays independent of the row's expand/collapse and context menu.
function VisibilityToggle({
  visible,
  label,
  onToggle,
}: {
  visible: boolean;
  label: string;
  onToggle: () => void;
}) {
  const Icon = visible ? Eye : EyeOff;
  return (
    // A role="button" span (not a real <button>) — this sits inside TreeItem's
    // row <button>, where nested interactive <button>s would be invalid markup.
    <span
      role="button"
      tabIndex={0}
      aria-label={`${visible ? 'Hide' : 'Show'} ${label} layer`}
      title={visible ? 'Hide layer' : 'Show layer'}
      onClick={(e) => {
        e.stopPropagation();
        onToggle();
      }}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          e.stopPropagation();
          onToggle();
        }
      }}
      className={`grid h-5 w-5 shrink-0 place-items-center rounded hover:bg-accent ${
        visible ? 'text-foreground' : 'text-muted-foreground/60'
      }`}
    >
      <Icon className="h-3.5 w-3.5" />
    </span>
  );
}

/**
 * Generic row-trailing icon button (a `role="button"` span, for the same
 * nested-interactive reason as {@link VisibilityToggle}). Used for the group
 * row's two side-by-side CTAs — `muted` dims the icon to signal a hidden state.
 */
function IconToggle({
  icon: Icon,
  muted,
  ariaLabel,
  title,
  onToggle,
}: {
  icon: ElementType;
  muted: boolean;
  ariaLabel: string;
  title: string;
  onToggle: () => void;
}) {
  return (
    <span
      role="button"
      tabIndex={0}
      aria-label={ariaLabel}
      title={title}
      onClick={(e) => {
        e.stopPropagation();
        onToggle();
      }}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          e.stopPropagation();
          onToggle();
        }
      }}
      className={`grid h-5 w-5 shrink-0 place-items-center rounded hover:bg-accent ${
        muted ? 'text-muted-foreground/60' : 'text-foreground'
      }`}
    >
      <Icon className="h-3.5 w-3.5" />
    </span>
  );
}

interface GroupOpts<T> {
  prefix: string;
  kind: 'node' | 'edge';
  typeIcon: ElementType;
  leafIcon: ElementType;
  labelOf: (el: T) => string;
  isHidden: (el: T) => boolean;
  /** When true (the owning layer is hidden), strike every row regardless of the
   *  element's own hidden flag. */
  forceHidden: boolean;
  ctx: RowCtx;
}

// Group an iterable of graph elements by `type` into sorted "type · count"
// branches, each expanding into its (capped) individual elements.
//
// Scale note: we iterate the source exactly once and keep at most `limit`
// elements per type in memory — we never materialise the full 500k-edge set
// into arrays. Cost is O(total) time, O(#types × shown) memory, so a huge canvas
// stays cheap. Counts are still exact because we tally every element.
function groupByType<T extends { id: string; type?: string }>(
  entries: Iterable<T>,
  opts: GroupOpts<T>,
): { groups: TreeItem[]; total: number } {
  const { prefix, kind, typeIcon, leafIcon, labelOf, isHidden, forceHidden, ctx } = opts;
  const counts = new Map<string, number>();
  const samples = new Map<string, T[]>();
  let total = 0;
  for (const el of entries) {
    total += 1;
    const type = el.type ?? '(untyped)';
    counts.set(type, (counts.get(type) ?? 0) + 1);
    let bucket = samples.get(type);
    if (!bucket) {
      bucket = [];
      samples.set(type, bucket);
    }
    if (bucket.length < ctx.limitFor(`${prefix}:${type}`)) bucket.push(el);
  }
  const TypeIcon = typeIcon;
  const LeafIcon = leafIcon;
  const groups: TreeItem[] = [...counts.entries()]
    .sort((a, b) => a[0].localeCompare(b[0]))
    .map(([type, count]) => {
      const key = `${prefix}:${type}`;
      const shown = samples.get(type) ?? [];
      const children: TreeItem[] = shown.map((el) => {
        const id = String(el.id);
        const hidden = isHidden(el) || forceHidden;
        return {
          id: `${key}:${id}`,
          label: '',
          icon: (
            <RowContent
              icon={
                hidden ? (
                  <EyeOff className="h-3 w-3 shrink-0 text-muted-foreground/50" />
                ) : (
                  <LeafIcon className="h-3 w-3 shrink-0 text-muted-foreground/70" />
                )
              }
              label={labelOf(el)}
              muted={hidden}
              menuTarget={{ kind, id }}
            />
          ),
          onClick: () => ctx.onLeafClick(kind, id),
        };
      });
      const remaining = count - children.length;
      if (remaining > 0) {
        children.push({
          id: `${key}:__more`,
          label: '',
          icon: (
            <RowContent
              icon={<MoreHorizontal className="h-3 w-3 shrink-0 text-muted-foreground/50" />}
              label={
                remaining <= REVEAL_STEP
                  ? `Show ${remaining} more`
                  : `Show ${REVEAL_STEP} more of ${remaining}`
              }
              muted={forceHidden}
            />
          ),
          onClick: () => ctx.onReveal(key),
        });
      }
      return {
        id: key,
        label: '',
        icon: (
          <RowContent
            key={type}
            icon={<TypeIcon className="h-3 w-3 shrink-0 text-muted-foreground" />}
            label={`${type} · ${count}`}
            muted={forceHidden}
          />
        ),
        children,
      };
    });
  return { groups, total };
}

// Friendly label + icon per known layer id. Layer *ids* are stable ("background"
// / "graph" / "minimap"); class names get mangled in production builds, so we key
// off the id rather than `constructor.name`.
const LAYER_META: Record<string, { label: string; icon: ElementType }> = {
  graph: { label: 'Graph', icon: Network },
  background: { label: 'Background', icon: ImageIcon },
  minimap: { label: 'Minimap', icon: MapIcon },
};

// Derive the layer tree from the live canvas. Layer ids are stable, so the
// TreeView keys off them and preserves each row's expand state across renders.
// Build the "Groups" section — every container node (`layer.isGroupNode`, i.e.
// `style.group`) as a row with an eye that hides/shows the whole subtree, each
// expanding into its direct member nodes. Returns `null` when the graph has no
// groups (so the section is omitted). `layer` is `GraphLayer` (typed loosely to
// avoid widening the type-only import surface).
function buildGroupsSection(
  layer: GraphLayer,
  store: GraphStore,
  ctx: RowCtx,
  forceHidden: boolean,
): TreeItem | null {
  const groupIds: string[] = [];
  for (const n of store.nodes()) {
    if (layer.isGroupNode(n)) groupIds.push(String(n.id));
  }
  if (groupIds.length === 0) return null;
  groupIds.sort((a, b) => a.localeCompare(b));

  const groupRows: TreeItem[] = groupIds.map((gid) => {
    const gnode = store.getNode(gid);
    const gLabel = elementLabel(gnode?.data, gid);
    // Two independent visibility axes for a group:
    //  · frameHidden — the container node itself (its silhouette/frame).
    //  · allHidden   — frame AND every member hidden (the whole group is gone).
    // "Hide group only" toggles the frame; "Hide group + members" toggles the
    // whole subtree. Tracking both lets the two CTAs show distinct states — e.g.
    // frame hidden but members still visible.
    const frameHidden = layer.isGroupHidden(gid);
    let allHidden = frameHidden;
    if (frameHidden) {
      for (const descId of store.descendantsOf(gid)) {
        if (!store.isNodeHidden(descId)) {
          allHidden = false;
          break;
        }
      }
    }
    const frameMuted = frameHidden || forceHidden;
    const allMuted = allHidden || forceHidden;
    const gHidden = frameHidden || forceHidden;
    // Member rows — the group's direct `parentId` children.
    const memberRows: TreeItem[] = [];
    for (const mid of store.childrenOf(gid)) {
      const id = String(mid);
      const m = store.getNode(id);
      const hidden = store.isNodeHidden(id) || forceHidden;
      memberRows.push({
        id: `graph:group:${gid}:member:${id}`,
        label: '',
        icon: (
          <RowContent
            icon={
              hidden ? (
                <EyeOff className="h-3 w-3 shrink-0 text-muted-foreground/50" />
              ) : (
                <Circle className="h-3 w-3 shrink-0 text-muted-foreground/70" />
              )
            }
            label={elementLabel(m?.data, id)}
            muted={hidden}
            menuTarget={{ kind: 'node', id }}
          />
        ),
        onClick: () => ctx.onLeafClick('node', id),
      });
    }
    return {
      id: `graph:group:${gid}`,
      label: '',
      icon: (
        <RowContent
          icon={
            gHidden ? (
              <EyeOff className="h-3 w-3 shrink-0 text-muted-foreground/50" />
            ) : (
              <Boxes className="h-3 w-3 shrink-0 text-muted-foreground/70" />
            )
          }
          label={gLabel}
          muted={gHidden}
          menuTarget={{ kind: 'group', id: gid }}
          trailing={
            <span className="flex items-center gap-0.5">
              {/* Frame only — hides/shows just the container; members stay. */}
              <IconToggle
                icon={Frame}
                muted={frameMuted}
                ariaLabel={`${frameHidden ? 'Show' : 'Hide'} ${gLabel} group frame only`}
                title={frameHidden ? 'Show group frame' : 'Hide group frame only'}
                onToggle={() => {
                  if (frameHidden) layer.showNode(gid);
                  else layer.hideNode(gid);
                  ctx.refresh();
                }}
              />
              {/* Group + members — hides/shows the whole subtree. */}
              <IconToggle
                icon={allMuted ? EyeOff : Eye}
                muted={allMuted}
                ariaLabel={`${allHidden ? 'Show' : 'Hide'} ${gLabel} group and members`}
                title={allHidden ? 'Show group + members' : 'Hide group + members'}
                onToggle={() => {
                  if (allHidden) layer.showGroup(gid);
                  else layer.hideGroup(gid);
                  ctx.refresh();
                }}
              />
            </span>
          }
        />
      ),
      children: memberRows.length > 0 ? memberRows : undefined,
    };
  });

  return {
    id: 'graph:groups',
    label: '',
    icon: (
      <RowContent
        icon={<Boxes className="h-3.5 w-3.5 shrink-0 text-muted-foreground" />}
        label={`Groups · ${groupIds.length}`}
        muted={forceHidden}
      />
    ),
    children: groupRows,
  };
}

function buildItems(canvas: GraphCanvas | null, ctx: RowCtx): TreeItem[] {
  if (!canvas) return [];
  // Top layer first (byZOrder is low → high), mirroring how layers stack on
  // screen and how design tools list them.
  const layers = [...canvas.layers.byZOrder()].reverse();
  return layers.map((layer) => {
    const meta = LAYER_META[layer.id] ?? { label: layer.id, icon: Layers };
    const LayerIcon = meta.icon;
    // The graph layer expands into its painted contents grouped by type, plus a
    // Groups section for container nodes (`style.group`) and their members.
    let children: TreeItem[] | undefined;
    if (layer.id === 'graph') {
      const graphLayer = canvas.layers.get<GraphLayer>('graph');
      const store = graphLayer?.store;
      if (store && graphLayer) {
        // A hidden graph layer strikes every descendant row (the whole subtree
        // is not painted), regardless of each element's own hidden flag.
        const forceHidden = !graphLayer.visible;
        const nodes = groupByType(store.nodes(), {
          prefix: 'graph:node',
          kind: 'node',
          typeIcon: Circle,
          leafIcon: Circle,
          labelOf: (n) => elementLabel(n.data, String(n.id)),
          isHidden: (n) => store.isNodeHidden(String(n.id)),
          forceHidden,
          ctx,
        });
        const edges = groupByType(store.edges(), {
          prefix: 'graph:edge',
          kind: 'edge',
          typeIcon: Spline,
          leafIcon: ArrowRight,
          labelOf: (e) => `${e.source} → ${e.target}`,
          isHidden: (e) => store.isEdgeHidden(String(e.id)),
          forceHidden,
          ctx,
        });
        const groupsSection = buildGroupsSection(graphLayer, store, ctx, forceHidden);
        children = [
          {
            id: 'graph:nodes',
            label: '',
            icon: (
              <RowContent
                icon={<Circle className="h-3.5 w-3.5 shrink-0 text-muted-foreground" />}
                label={`Nodes · ${nodes.total}`}
                muted={forceHidden}
              />
            ),
            children: nodes.groups,
          },
          {
            id: 'graph:edges',
            label: '',
            icon: (
              <RowContent
                icon={<Spline className="h-3.5 w-3.5 shrink-0 text-muted-foreground" />}
                label={`Edges · ${edges.total}`}
                muted={forceHidden}
              />
            ),
            children: edges.groups,
          },
          ...(groupsSection ? [groupsSection] : []),
        ];
      }
    }
    return {
      id: layer.id,
      label: '',
      icon: (
        <RowContent
          icon={<LayerIcon className="h-4 w-4 shrink-0 text-muted-foreground" />}
          label={meta.label}
          menuTarget={{ kind: 'layer', id: layer.id }}
          trailing={
            <VisibilityToggle
              visible={layer.visible}
              label={meta.label}
              onToggle={() => {
                layer.setVisible(!layer.visible);
                ctx.refresh();
              }}
            />
          }
        />
      ),
      children,
    } satisfies TreeItem;
  });
}

// ── Canvas actions ───────────────────────────────────────────────────────────

function graphRefs(canvas: GraphCanvas | null) {
  const layer = canvas?.layers.get<GraphLayer>('graph') ?? undefined;
  const select =
    canvas?.behaviours.get<ClickSelectBehaviour>('click-select') ?? undefined;
  return { layer, store: layer?.store, select };
}

function selectElement(
  canvas: GraphCanvas | null,
  kind: 'node' | 'edge',
  id: string,
) {
  graphRefs(canvas).select?.select(id, kind === 'node' ? 'shape' : 'connector');
}

function focusElement(
  canvas: GraphCanvas | null,
  kind: 'node' | 'edge',
  id: string,
) {
  const { layer, select } = graphRefs(canvas);
  if (kind === 'node') {
    select?.select(id, 'shape');
    layer?.focusNode(id, { zoom: FOCUS_ZOOM });
  } else {
    select?.select(id, 'connector');
    layer?.focusEdges([id]);
  }
}

// Hide/show a single element through the first-class visibility API. Hiding a
// node culls it and — via the store's derived cascade — its incident edges, in
// one batch → one flush → one paint. No manual edge bookkeeping.
function setElementHidden(
  store: GraphStore,
  kind: 'node' | 'edge',
  id: string,
  hidden: boolean,
) {
  if (kind === 'node') store.setNodeHidden(id, hidden);
  else store.setEdgeHidden(id, hidden);
}

// ── Context menu ─────────────────────────────────────────────────────────────

function ContextMenuItems({
  canvas,
  target,
  refresh,
}: {
  canvas: GraphCanvas | null;
  target: MenuTarget;
  refresh: () => void;
}) {
  if (target.kind === 'layer') {
    const layer = canvas?.layers.get(target.id);
    const visible = layer?.visible ?? true;
    return (
      <DropdownMenuContent align="start" className="w-44">
        {target.id === 'graph' && (
          <DropdownMenuItem
            onSelect={() => {
              const g = canvas?.layers.get<GraphLayer>('graph');
              if (g && canvas) canvas.camera.fitContent(g.getBounds(), 80);
            }}
          >
            <Crosshair className="mr-2 h-4 w-4" /> Focus layer
          </DropdownMenuItem>
        )}
        <DropdownMenuItem
          onSelect={() => {
            layer?.setVisible(!layer.visible);
            refresh();
          }}
        >
          {visible ? (
            <>
              <EyeOff className="mr-2 h-4 w-4" /> Hide layer
            </>
          ) : (
            <>
              <Eye className="mr-2 h-4 w-4" /> Show layer
            </>
          )}
        </DropdownMenuItem>
      </DropdownMenuContent>
    );
  }

  if (target.kind === 'group') {
    const layer = graphRefs(canvas).layer;
    const gid = target.id;
    // `isGroupHidden` reports the *container* node's own hidden flag.
    const gHidden = layer?.isGroupHidden(gid) ?? false;
    return (
      <DropdownMenuContent align="start" className="w-52">
        <DropdownMenuItem onSelect={() => layer?.focusNode(gid, { zoom: FOCUS_ZOOM })}>
          <Crosshair className="mr-2 h-4 w-4" /> Focus on group
        </DropdownMenuItem>
        <DropdownMenuSeparator />
        {gHidden ? (
          <>
            {/* Show just the container frame (members unaffected). */}
            <DropdownMenuItem onSelect={() => { layer?.showNode(gid); refresh(); }}>
              <Eye className="mr-2 h-4 w-4" /> Show group only
            </DropdownMenuItem>
            {/* Show the container + its whole subtree. */}
            <DropdownMenuItem onSelect={() => { layer?.showGroup(gid); refresh(); }}>
              <Eye className="mr-2 h-4 w-4" /> Show group + members
            </DropdownMenuItem>
          </>
        ) : (
          <>
            {/* Hide just the container frame; members stay visible (no cascade). */}
            <DropdownMenuItem onSelect={() => { layer?.hideNode(gid); refresh(); }}>
              <EyeOff className="mr-2 h-4 w-4" /> Hide group only
            </DropdownMenuItem>
            {/* Hide the container + its whole subtree, one paint. */}
            <DropdownMenuItem onSelect={() => { layer?.hideGroup(gid); refresh(); }}>
              <EyeOff className="mr-2 h-4 w-4" /> Hide group + members
            </DropdownMenuItem>
          </>
        )}
      </DropdownMenuContent>
    );
  }

  const { kind, id } = target;
  const store = graphRefs(canvas).store;
  const hidden =
    kind === 'node'
      ? (store?.isNodeHidden(id) ?? false)
      : (store?.isEdgeHidden(id) ?? false);
  const noun = kind === 'node' ? 'node' : 'edge';
  return (
    <DropdownMenuContent align="start" className="w-44">
      <DropdownMenuItem onSelect={() => focusElement(canvas, kind, id)}>
        <Crosshair className="mr-2 h-4 w-4" /> Focus on {noun}
      </DropdownMenuItem>
      <DropdownMenuItem onSelect={() => selectElement(canvas, kind, id)}>
        <MousePointer2 className="mr-2 h-4 w-4" /> Select {noun}
      </DropdownMenuItem>
      <DropdownMenuSeparator />
      <DropdownMenuItem
        onSelect={() => {
          if (!store) return;
          setElementHidden(store, kind, id, !hidden);
          refresh();
        }}
      >
        {hidden ? (
          <>
            <Eye className="mr-2 h-4 w-4" /> Show {noun}
          </>
        ) : (
          <>
            <EyeOff className="mr-2 h-4 w-4" /> Hide {noun}
          </>
        )}
      </DropdownMenuItem>
    </DropdownMenuContent>
  );
}

export function LayersViewPanel({ canvas: explicit }: LayersViewPanelProps) {
  // Self-wiring: bind to an explicit `canvas` if given, else the nearest
  // `<GraphCanvas>` / `GraphCanvasApp` via context (null until the engine is
  // ready — the panel simply renders empty). `useContext` runs unconditionally
  // so the `??` can't short-circuit a hook.
  const contextCanvas = useContext(GraphCanvasContext);
  const canvas = explicit ?? contextCanvas;

  // Layers/store are live mutable canvas state, not React state — bumping `rev`
  // re-derives the tree. `rev` is a dependency of the memo below, never read.
  const [rev, bumpRev] = useReducer((n: number) => n + 1, 0);
  // Cursor-anchored context menu (a controlled DropdownMenu opened at the click
  // point, since the design kit has no standalone ContextMenu component).
  const [menu, setMenu] = useState<{
    x: number;
    y: number;
    target: MenuTarget;
  } | null>(null);
  // The row button currently kept highlighted while its menu is open.
  const activeRowRef = useRef<HTMLElement | null>(null);
  const clearActiveRow = useCallback(() => {
    activeRowRef.current?.classList.remove(...ACTIVE_ROW_CLASSES);
    activeRowRef.current = null;
  }, []);

  // One delegated right-click handler for the whole tree. Resolving the target
  // from the row `<button>` (rather than an `onContextMenu` per row body) means a
  // click anywhere in the row — text, icon, padding, blank space — hits it, and
  // the native browser menu is always suppressed inside the tree.
  const handleContextMenu = useCallback(
    (e: ReactMouseEvent<HTMLElement>) => {
      e.preventDefault();
      clearActiveRow();
      const row = (e.target as HTMLElement).closest('button');
      const holder = row?.querySelector<HTMLElement>('[data-menu-id]');
      const kind = holder?.dataset.menuKind as MenuTarget['kind'] | undefined;
      const id = holder?.dataset.menuId;
      // Rows without a menu (group / type / "Show more") still land here so the
      // native menu is suppressed, but open nothing.
      if (!row || !kind || !id) {
        setMenu(null);
        return;
      }
      row.classList.add(...ACTIVE_ROW_CLASSES);
      activeRowRef.current = row;
      setMenu({
        x: e.clientX,
        y: e.clientY,
        target: { kind, id } as MenuTarget,
      });
    },
    [clearActiveRow],
  );

  const onLeafClick = useCallback(
    (kind: 'node' | 'edge', id: string) => selectElement(canvas, kind, id),
    [canvas],
  );

  // Per-type reveal counts (progressive disclosure). Held in a ref so they
  // survive tree rebuilds; changing one bumps `rev` to re-derive.
  const shownRef = useRef<Map<string, number>>(new Map());
  const limitFor = useCallback(
    (typeKey: string) => shownRef.current.get(typeKey) ?? DEFAULT_SHOWN,
    [],
  );
  const reveal = useCallback((typeKey: string) => {
    const cur = shownRef.current.get(typeKey) ?? DEFAULT_SHOWN;
    shownRef.current.set(typeKey, cur + REVEAL_STEP);
    bumpRev();
  }, []);

  // Coalesce store churn into one rebuild per frame. A bulk load / bulk hide
  // emits one event per element; without this each would trigger a full re-scan
  // of the store. The rAF guard collapses them to a single rebuild after the
  // batch settles.
  const frameRef = useRef<number | null>(null);
  const scheduleRebuild = useCallback(() => {
    if (frameRef.current !== null) return;
    frameRef.current = requestAnimationFrame(() => {
      frameRef.current = null;
      bumpRev();
    });
  }, []);

  useEffect(() => {
    if (!canvas) return;
    const graph = canvas.layers.get<GraphLayer>('graph');
    const store = graph?.store;
    const unsubs: Array<() => void> = [];
    if (store) {
      // Topology + visibility churn → rebuild the tree (counts + eye state).
      const storeEvents = [
        'node:add',
        'node:remove',
        'edge:add',
        'edge:remove',
        'node:visibility',
        'edge:visibility',
      ] as const;
      for (const ev of storeEvents) unsubs.push(store.events.on(ev, scheduleRebuild));
    }
    // Aggregated per-flush data change on the layer — the reliable "graph
    // changed" signal that also covers a bulk `setData` / layout run whose
    // per-node events may have fired before this panel subscribed.
    if (graph) unsubs.push(graph.events.on('data:changed', scheduleRebuild));
    // Group container hidden/shown as a unit → refresh the Groups section.
    if (graph) unsubs.push(graph.events.on('group:visibility', scheduleRebuild));
    // Whole-layer visibility toggled anywhere (this panel or elsewhere) → keep
    // the layer eyes in sync; a layer added later → pick it up.
    unsubs.push(canvas.events.on('scene:layer:visibilitychange', scheduleRebuild));
    unsubs.push(canvas.events.on('scene:layer:add', scheduleRebuild));
    // Initial pull: the graph's data is usually loaded (and its `node:add`
    // events already fired) before this effect runs, so re-read the current
    // store once on mount instead of waiting for the next mutation / a manual
    // refresh.
    scheduleRebuild();
    return () => {
      for (const off of unsubs) off();
      if (frameRef.current !== null) {
        cancelAnimationFrame(frameRef.current);
        frameRef.current = null;
      }
    };
  }, [canvas, scheduleRebuild]);

  const ctx = useMemo<RowCtx>(
    () => ({ limitFor, onReveal: reveal, onLeafClick, refresh: bumpRev }),
    [limitFor, reveal, onLeafClick],
  );

  // Memoised so unrelated parent re-renders don't re-scan the store; recomputes
  // only when the canvas swaps, `rev` bumps (mutation settle / reveal / toggle /
  // menu action), or the row context changes.
  // `rev` is the rebuild signal — the tree reads live mutable canvas/store state,
  // so `rev` (not the state itself) is what invalidates the memo.
  // eslint-disable-next-line react-hooks/exhaustive-deps
  const items = useMemo(() => buildItems(canvas, ctx), [canvas, ctx, rev]);

  // Self-contained panel chrome: a full-height flex column (fills the side-dock
  // `<Panel>`) with a `shrink-0` header and a `flex-1 min-h-0` scrolling body, so
  // a tall tree scrolls *inside* the panel instead of overflowing past it.
  return (
    <div className="flex h-full flex-col overflow-hidden bg-popover text-popover-foreground">
      <div className="min-h-0 flex-1 overflow-y-auto p-2">
        {items.length === 0 ? (
          <div className="flex h-full flex-col items-center justify-center gap-2 px-6 text-center text-muted-foreground">
            <Layers className="h-6 w-6" />
            <p className="text-base">No canvas layers</p>
            <p className="text-sm">Mount a canvas to see its layers.</p>
          </div>
        ) : (
          <div onContextMenu={handleContextMenu}>
            <TreeView
              items={items}
              className="w-full border-0 bg-transparent p-0 shadow-none"
            />
            <DropdownMenu
              open={menu !== null}
              onOpenChange={(open) => {
                if (!open) {
                  clearActiveRow();
                  setMenu(null);
                }
              }}
            >
              <DropdownMenuTrigger asChild>
                <span
                  aria-hidden
                  className="pointer-events-none fixed h-0 w-0"
                  style={{ left: menu?.x ?? 0, top: menu?.y ?? 0 }}
                />
              </DropdownMenuTrigger>
              {menu && (
                <ContextMenuItems
                  canvas={canvas}
                  target={menu.target}
                  refresh={bumpRev}
                />
              )}
            </DropdownMenu>
          </div>
        )}
      </div>
    </div>
  );
}
